import java.util.Arrays;

public class ArrayDemo {
    public static void main(String[] args) {
        // Declaration and initialization
        int[] numbers = {10, 20, 30, 40, 50};

        // Declaration then allocation
        int[] scores = new int[5];
        scores[0] = 85;
        scores[1] = 90;

        // Array length
        System.out.println("Length: " + numbers.length);

        // Accessing elements
        System.out.println("First: " + numbers[0]);
        System.out.println("Last: " + numbers[numbers.length - 1]);

        // Iterating
        for (int i = 0; i < numbers.length; i++) {
            System.out.print(numbers[i] + " ");
        }
        System.out.println();

        // for-each loop
        for (int num : numbers) {
            System.out.print(num + " ");
        }
        System.out.println();

        // Arrays utility class
        Arrays.sort(scores);
        System.out.println("Sorted: " + Arrays.toString(scores));

        // Multi-dimensional arrays
        int[][] matrix = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };
        System.out.println("matrix[1][2] = " + matrix[1][2]);
    }
}

public class StringDemo {
    public static void main(String[] args) {
        // String literals (stored in string pool)
        String s1 = "Hello";
        String s2 = "Hello";
        System.out.println("s1 == s2: " + (s1 == s2)); // true (same pool object)

        // String objects (stored in heap)
        String s3 = new String("Hello");
        System.out.println("s1 == s3: " + (s1 == s3)); // false (different objects)
        System.out.println("s1.equals(s3): " + s1.equals(s3)); // true (same content)

        // Common String methods
        String text = "  Hello, Java World!  ";
        System.out.println("Length: " + text.length());
        System.out.println("Upper: " + text.toUpperCase());
        System.out.println("Lower: " + text.toLowerCase());
        System.out.println("Trim: [" + text.trim() + "]");
        System.out.println("Contains 'Java': " + text.contains("Java"));
        System.out.println("Replace: " + text.replace("Java", "Rust"));
        System.out.println("Substring: " + text.substring(9, 13));
        System.out.println("Starts with '  H': " + text.startsWith("  H"));

        // String concatenation
        String first = "Hello";
        String second = "World";
        String combined = first + " " + second;
        System.out.println("Combined: " + combined);

        // StringBuilder for mutable strings
        StringBuilder sb = new StringBuilder();
        sb.append("Hello");
        sb.append(" ");
        sb.append("World");
        System.out.println("StringBuilder: " + sb.toString());
    }
}
